""" Return path to SQLite database file.

    Args:
        spider_dir: path to SPIDER benchmark
        db_id: database identifier

    Returns:
        path to SQLite database file
    """
def get_db_path(spider_dir: Any, db_id: Any) -> object {
    return f'{spider_dir}/database/{db_id}/{db_id}.sqlite';
}

test_blocks:
test "t0" {
    assert (
        get_db_path('/path/to/spider', 'spider')
        == '/path/to/spider/database/spider/spider.sqlite'
    );;
}

test "t1" {
    assert (get_db_path('a', 'b') == 'a/database/b/b.sqlite');;
}

test "t2" {
    assert (
        get_db_path('~/spider/data', 'dev') == '~/spider/data/database/dev/dev.sqlite'
    );;
}

test "t3" {
    assert (get_db_path('spider', 'sparc') == 'spider/database/sparc/sparc.sqlite');;
}

test "t4" {
    assert (
        get_db_path('SPIDER_PATH', 'SPIDER_DB_ID')
        == 'SPIDER_PATH/database/SPIDER_DB_ID/SPIDER_DB_ID.sqlite'
    );;
}

test "t5" {
    assert (get_db_path('foo', 'bar') == 'foo/database/bar/bar.sqlite');;
}

test "t6" {
    assert (
        get_db_path('spider', 'geography')
        == 'spider/database/geography/geography.sqlite'
    );;
}

